INSERT INTO exercises (external_id, name, muscle_group, secondary_muscles, equipment, category, level, instructions) VALUES
('Smith_Machine_Calf_Raise', 'Smith Machine Calf Raise', 'legs', ARRAY[]::text[], 'machine', 'strength', 'beginner', 'Place a block or weight plate below the bar on the Smith machine. Set the bar to a position that best matches your height. Once the correct height is chosen and the bar is loaded, step onto the plates with the balls of your feet and place the bar on the back of your shoulders. Take the bar with both hands facing forward. Rotate the bar to unrack it. This will be your starting position. Raise your heels as high as possible by pushing off of the balls of your feet, flexing your calf at the top of '),
('Smith_Machine_Close-Grip_Bench_Press', 'Smith Machine Close-Grip Bench Press', 'arms', ARRAY['chest','shoulders']::text[], 'machine', 'strength', 'beginner', 'Place a flat bench underneath the smith machine. Place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the flat bench. Using a close and pronated grip (palms facing forward) that is around shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position. As you breathe in, come down slowly until you feel the bar on your middle '),
('Smith_Machine_Decline_Press', 'Smith Machine Decline Press', 'chest', ARRAY['shoulders','arms']::text[], 'machine', 'strength', 'beginner', 'Position a decline bench in the rack so that the bar will be above your chest. Load an appropriate weight and take your place on the bench. Rotate the bar to unhook it from the rack and fully extend your arms. Your back should be slightly arched and your shoulder blades retracted. This will be your starting position. Begin the movement by flexing your arms, lowering the bar to your chest. Pause briefly, and then extend your arms to push the weight back to the starting position. After completing '),
('Smith_Machine_Hang_Power_Clean', 'Smith Machine Hang Power Clean', 'legs', ARRAY['legs','back','legs','shoulders','back']::text[], 'machine', 'strength', 'intermediate', 'Position the bar at knee height and load it to an appropriate weight. Take a pronated grip on the bar outside of shoulder width and unhook the bar from the machine. Your arms should be fully extended with your head and chest up. Your elbows should be pointed out with your shoulders back and down. Your hips should be back, loading the tension into the hamstrings. This will be your starting position. Initate the movement by forcefully extending the hips and knees, accelerating into the bar. Ensure'),
('Smith_Machine_Hip_Raise', 'Smith Machine Hip Raise', 'core', ARRAY[]::text[], 'machine', 'strength', 'beginner', 'Position a bench in the rack and load the bar to an appropriate weight. Lie down on the bench, placing the bottom of your feet against the bar. Unlock the bar and extend your legs. You may need to use your hands to assist you. For added stability grasp the sides of the Smith Machine. This will be your starting position. Initiate the movement by rotating your pelvis, flexing your spine to raise your hips off of the bench. Maintain a slight bend in the knees throughout the motion. After a brief pa'),
('Smith_Machine_Incline_Bench_Press', 'Smith Machine Incline Bench Press', 'chest', ARRAY['shoulders','arms']::text[], 'machine', 'strength', 'beginner', 'Place an incline bench underneath the smith machine. Place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the incline bench and make sure your upper chest is aligned with the barbell. Using a pronated grip (palms facing forward) that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position. As you breathe'),
('Smith_Machine_Leg_Press', 'Smith Machine Leg Press', 'legs', ARRAY['legs','legs','legs']::text[], 'machine', 'strength', 'intermediate', 'Position a Smith machine bar a couple feet off of the ground. Ensure that it is resting on the safeties. After loading the bar to an appropriate weight, lie underneath the bar. Place the middle of your feet on the bar, tucking your knees to your chest. This will be your starting position. Begin the movement by driving through your feet to move the bar upward, extending the hips and knees. Do not lock out your knees. At the top of the motion, pause briefly before returning to the starting positio'),
('Smith_Machine_One-Arm_Upright_Row', 'Smith Machine One-Arm Upright Row', 'shoulders', ARRAY['arms','back']::text[], 'machine', 'strength', 'beginner', 'With the bar at thigh level, load an appropriate weight. Take a wide grip on the bar and unhook the weight, removing your off hand from the bar. Your arm should be extended as you stand up straight with your head and chest up. This will be your starting position. Begin the movement by flexing the elbow, raising the upper arm with the elbow pointed out. Continue until your upper arm is parallel to the floor. After a brief pause, return the weight to the starting position. Repeat for the desired n'),
('Smith_Machine_Overhead_Shoulder_Press', 'Smith Machine Overhead Shoulder Press', 'shoulders', ARRAY['arms']::text[], 'machine', 'strength', 'beginner', 'To begin, place a flat bench (or preferably one with back support) underneath a smith machine. Position the barbell at a height so that when seated on the flat bench, the arms must be almost fully extended to reach the barbell. Once you have the correct height, sit slightly in behind the barbell so that there is an imaginary straight line from the tip of your nose to the barbell. Your feet should be stationary. Grab the barbell with the palms facing forward, unlock it and lift it up so that your'),
('Smith_Machine_Pistol_Squat', 'Smith Machine Pistol Squat', 'legs', ARRAY['legs','legs','legs']::text[], 'machine', 'strength', 'intermediate', 'To begin, first set the bar to a position that best matches your height. Step under it and position the bar across the back of your shoulders. Take the bar with your hands facing forward, unlock it and lift it off the rack by extending your legs. 3 Move one foot forward about 12 inches in front of the bar. Extend the other leg out in front of you, holding it off the ground. Look forward at all times and maintain a neutral or slightly arched spine. This will be your starting position. Maintaining'),
('Smith_Machine_Reverse_Calf_Raises', 'Smith Machine Reverse Calf Raises', 'legs', ARRAY[]::text[], 'machine', 'strength', 'beginner', 'Adjust the barbell on the smith machine to fit your height and align a raised platform right under the bar. Stand on the platform with the heels of your feet secured on top of it with the balls of your feet extending off it. Position your toes facing forward with a shoulder width stance. Now, place your shoulders under the barbell while maintaining the foot positioning described and push the barbell up by extending your hips and knees until your torso is standing erect. The knees should be kept '),
('Smith_Machine_Squat', 'Smith Machine Squat', 'legs', ARRAY['legs','legs','legs','back']::text[], 'machine', 'strength', 'beginner', 'To begin, first set the bar on the height that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it. Hold on to the bar using both arms at each side (palms facing forward), unlock it and lift it off the rack by first pushing with your legs and at the same time straightening your torso. Position your legs using a shoulder width medium stance with the toes slightly pointed out.'),
('Smith_Machine_Stiff-Legged_Deadlift', 'Smith Machine Stiff-Legged Deadlift', 'legs', ARRAY['legs','back']::text[], 'machine', 'strength', 'beginner', 'To begin, set the bar on the smith machine to a height that is around the middle of your thighs. Once the correct height is chosen and the bar is loaded, grasp the bar using a pronated (palms forward) grip that is shoulder width apart. You may need some wrist wraps if using a significant amount of weight. Lift the bar up by fully extending your arms while keeping your back straight. Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be'),
('Smith_Machine_Upright_Row', 'Smith Machine Upright Row', 'back', ARRAY['arms','back','shoulders']::text[], 'machine', 'strength', 'beginner', 'To begin, set the bar on the smith machine to a height that is around the middle of your thighs. Once the correct height is chosen and the bar is loaded, grasp the bar using a pronated (palms forward) grip that is shoulder width apart. You may need some wrist wraps if using a significant amount of weight. Lift the barbell up and fully extend your arms with your back straight. There should be a slight bend at the elbows. This is the starting position. Use your side shoulders to lift the bar as yo'),
('Smith_Single-Leg_Split_Squat', 'Smith Single-Leg Split Squat', 'legs', ARRAY['legs','legs','legs']::text[], 'machine', 'strength', 'beginner', 'To begin, place a flat bench 2-3 feet behind the smith machine. Then, set the bar on the height that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it. Hold on to the bar using both arms at each side (palms facing forward), unlock it and lift it off the rack by first pushing with your legs and at the same time straightening your torso. Position your legs by placing one foo'),
('Snatch', 'Snatch', 'legs', ARRAY['arms','legs','legs','back','shoulders','back','arms']::text[], 'barbell', 'olympic weightlifting', 'intermediate', 'Place your feet at a shoulder width stance with the barbell resting right above the connection between the toes and the rest of the foot. With a palms facing down grip, bend at the knees and keeping the back flat grab the bar using a wider than shoulder width grip. Bring the hips down and make sure that your body drops as if you were going to sit on a chair. This will be your starting position. Start pushing the floor as if it were a moving platform with your feet and simultaneously start liftin'),
('Snatch_Balance', 'Snatch Balance', 'legs', ARRAY['legs','legs','legs','shoulders','arms']::text[], 'barbell', 'olympic weightlifting', 'intermediate', 'Begin with the feet in the pulling position, the bar racked across the back of the shoulders, and the hands placed in a wide snatch grip. Pop the bar with an abrupt dip and drive of the knees, and aggressively drive under the bar, transitioning the feet into the receiving position. Receive the bar locked out overhead near the bottom of the squat. The torso should remain vertical, lowering the hips between the legs. Continue to descend to full depth, and return to a standing position. Carefully l'),
('Snatch_Deadlift', 'Snatch Deadlift', 'legs', ARRAY['arms','legs','legs','back','legs','back']::text[], 'barbell', 'olympic weightlifting', 'intermediate', 'The snatch deadlift strengthens the first pull of the snatch. Begin with a wide snatch grip with the barbell placed on the platform. The feet should be directly under the hips, with the feet turned out. Squat down to the bar, keeping the back in absolute extension with the head facing forward. Initiate the movement by driving through the heels, raising the hips. The back angle should remain the same until the bar passes the knees. At that point, drive your hips through the bar as you lay back. R'),
('Snatch_Pull', 'Snatch Pull', 'legs', ARRAY['legs','legs','back','legs','back']::text[], 'barbell', 'strength', 'intermediate', 'With a barbell on the floor close to the shins, take a wide snatch grip. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position. Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees. Next comes the second pull, th'),
('Snatch_Shrug', 'Snatch Shrug', 'back', ARRAY['arms','shoulders']::text[], 'barbell', 'olympic weightlifting', 'intermediate', 'Begin with a wide grip, with the bar hanging at the mid thigh position. You can use a hook or overhand grip. Your back should be straight and inclined slightly forward. Shrug your shoulders towards your ears. While this exercise can usually by loaded with heavier weight than a snatch, avoid overloading to the point that the execution slows down.'),
('Snatch_from_Blocks', 'Snatch from Blocks', 'legs', ARRAY['legs','arms','legs','legs','back','shoulders','back','arms']::text[], 'barbell', 'olympic weightlifting', 'expert', 'Begin with a loaded barbell on boxes or stands of the desired height. A wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar, with the elbows pointed out. This will be the starting position. Begin the first pull by driving through the front of the heels, raising the bar from the boxes. Transition into the second pull by '),
('Speed_Band_Overhead_Triceps', 'Speed Band Overhead Triceps', 'arms', ARRAY[]::text[], 'bands', 'strength', 'beginner', 'For this exercise anchor a band to the ground. We used an incline bench and anchored the band to the base, standing over the bench. Alternatively, this could be performed standing on the band. To begin, pull the band behind your head, holding it with a pronated grip and your elbows up. This will be your starting position. To perform the movement, extend through the elbow to to straighten your arms, ensuring that you keep your upper arm in place. Pause, and then return to the starting position.'),
('Speed_Box_Squat', 'Speed Box Squat', 'legs', ARRAY['legs','legs','legs']::text[], 'barbell', 'powerlifting', 'intermediate', 'Attach bands to the bar that are securely anchored near the ground. You may need to choke the bands to get adequate tension. Use a box of an appropriate height for this exercise. Load the bar to a weight that still requires effort, but isn''t so heavy that speed is compromised. Typically, that will be between 50-70% of your one rep max. Position the bar on your upper back, shoulder blades retracted, back arched and everything tight head to toe. This will be the starting position. Unrack the bar '),
('Speed_Squats', 'Speed Squats', 'legs', ARRAY['legs','legs','legs','back']::text[], 'barbell', 'strength', 'expert', 'This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs using a s'),
('Spell_Caster', 'Spell Caster', 'core', ARRAY['legs','shoulders']::text[], 'dumbbell', 'strength', 'beginner', 'Hold a dumbbell in each hand with a pronated grip. Your feet should be wide with your hips and knees extended. This will be your starting position. Begin the movement by pulling both of the dumbbells to one side next to your hip, rotating your torso. Keeping your arms straight and the dumbbells parallel to the ground, rotate your torso to swing the weights to your opposite side. Continue alternating, rotating from one side to the other until the set is complete.'),
('Spider_Crawl', 'Spider Crawl', 'core', ARRAY['chest','shoulders','arms']::text[], 'bodyweight', 'strength', 'beginner', 'Begin in a prone position on the floor. Support your weight on your hands and toes, with your feet together and your body straight. Your arms should be bent to 90 degrees. This will be your starting position. Initiate the movement by raising one foot off of the ground. Externally rotate the leg and bring the knee toward your elbow, as far forward as possible. Return this leg to the starting position and repeat on the opposite side.'),
('Spider_Curl', 'Spider Curl', 'arms', ARRAY[]::text[], 'barbell', 'strength', 'beginner', 'Start out by setting the bar on the part of the preacher bench that you would normally sit on. Make sure to align the barbell properly so that it is balanced and will not fall off. Move to the front side of the preacher bench (the part where the arms usually lay) and position yourself to lay at a 45 degree slant with your torso and stomach pressed against the front side of the preacher bench. Make sure that your feet (especially the toes) are well positioned on the floor and place your upper arm'),
('Spinal_Stretch', 'Spinal Stretch', 'back', ARRAY['back','back','other','back']::text[], 'other', 'stretching', 'beginner', 'Sit in a chair so your back is straight and your feet planted on the floor. Interlace your fingers behind your head, elbows out and your chin down. Twist your upper body to one side about 3 times as far as you can. Then lean forward and twist your torso to reach your elbow to the floor on the inside of your knee. Return to upright position and then repeat for your other side.'),
('Split_Clean', 'Split Clean', 'legs', ARRAY['legs','arms','legs','legs','back','shoulders','back']::text[], 'barbell', 'olympic weightlifting', 'intermediate', 'With a barbell on the floor close to the shins, take an overhand grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position. Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees. Next comes'),
('Split_Jerk', 'Split Jerk', 'legs', ARRAY['legs','legs','shoulders','arms']::text[], 'barbell', 'olympic weightlifting', 'intermediate', 'Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible. Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders. At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as'),
('Split_Jump', 'Split Jump', 'legs', ARRAY['legs','legs','legs']::text[], 'bodyweight', 'plyometrics', 'beginner', 'Assume a lunge stance position with one foot forward with the knee bent, and the rear knee nearly touching the ground. Ensure that the front knee is over the midline of the foot. Extending through both legs, jump as high as possible, swinging your arms to gain lift. As you jump, bring your feet together, and move them back to their initial positions as you land. Absorb the impact by reverting back to the starting position.'),
('Split_Snatch', 'Split Snatch', 'legs', ARRAY['legs','arms','legs','legs','back','legs','shoulders','back','arms']::text[], 'barbell', 'olympic weightlifting', 'expert', 'Begin with a loaded barbell on the floor. The bar should be close to or touching the shins, and a wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar. This will be the starting position. Begin the first pull by driving through the front of the heels, raising the bar from the ground. The back angle should stay the same u'),
('Split_Squat_with_Dumbbells', 'Split Squat with Dumbbells', 'legs', ARRAY['legs','legs']::text[], 'dumbbell', 'strength', 'beginner', 'Position yourself into a staggered stance with the rear foot elevated and front foot forward. Hold a dumbbell in each hand, letting them hang at the sides. This will be your starting position. Begin by descending, flexing your knee and hip to lower your body down. Maintain good posture througout the movement. Keep the front knee in line with the foot as you perform the exercise. At the bottom of the movement, drive through the heel to extend the knee and hip to return to the starting position.'),
('Split_Squats', 'Split Squats', 'legs', ARRAY['legs','legs','legs']::text[], 'other', 'stretching', 'intermediate', 'Being in a standing position. Jump into a split leg position, with one leg forward and one leg back, flexing the knees and lowering your hips slightly as you do so. As you descend, immediately reverse direction, standing back up and jumping, reversing the position of your legs. Repeat 5-10 times on each leg.'),
('Squat_Jerk', 'Squat Jerk', 'legs', ARRAY['legs','legs','legs','shoulders','arms']::text[], 'barbell', 'strength', 'expert', 'Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible. Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders. At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as'),
('Squat_with_Bands', 'Squat with Bands', 'legs', ARRAY['legs','legs','legs','legs','back']::text[], 'barbell', 'powerlifting', 'intermediate', 'Set up the bands on the sleeves, secured to either band pegs, the rack, or dumbbells so that there is appropriate tension. Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wide for more emphasis on the back, glutes, adductors, and '),
('Squat_with_Chains', 'Squat with Chains', 'legs', ARRAY['legs','legs','legs','legs','back']::text[], 'barbell', 'powerlifting', 'intermediate', 'To set up the chains, begin by looping the leader chain over the sleeves of the bar. The heavy chain should be attached using a snap hook. Adjust the length of the lead chain so that a few links are still on the floor at the top of the movement. Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch i'),
('Squat_with_Plate_Movers', 'Squat with Plate Movers', 'legs', ARRAY['legs','legs','legs','legs','legs']::text[], 'barbell', 'strength', 'intermediate', 'To begin, first set the bar on a rack to just below shoulder level. Position a weight plate on the ground a couple feet back from the rack. Once the bar is loaded, step under it and place the back of your shoulders across it. Hold on to the bar with both hands and lift it off the rack by first pushing with your legs and at the same time straighten your torso. Step away from the rack and adopt a wide stance with the toes slightly pointed out, with one foot on the weight plate. Keep your head up a'),
('Squats_-_With_Bands', 'Squats - With Bands', 'legs', ARRAY['legs','legs','legs','back']::text[], 'bands', 'strength', 'beginner', 'To start out, make sure that the exercise band is at an even split between both the left and right side of the body. To do this, use your hands to grab both sides of the band and place both feet in the middle of the band. Your feet should be shoulder width apart from each other. When holding the bands, they should be the same height on each side. You should be using a pronated grip (palms facing forward) and have the handles of the bands next to your face for this exercise. This is the starting '),
('Stairmaster', 'Stairmaster', 'legs', ARRAY['legs','legs','legs']::text[], 'machine', 'cardio', 'intermediate', 'To begin, step onto the stairmaster and select the desired option from the menu. You can choose a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Pump your legs up and down in an established rhythm, driving the pedals down but not all the way to the floor. It is recommended that you maintain your grip on the handles so that you don''t fall. The handles can be used to monitor your heart rat'),
('Standing_Alternating_Dumbbell_Press', 'Standing Alternating Dumbbell Press', 'shoulders', ARRAY['arms']::text[], 'dumbbell', 'strength', 'beginner', 'Stand with a dumbbell in each hand. Raise the dumbbells to your shoulders with your palms facing forward and your elbows pointed out. This will be your starting position. Extend one arm to press the dumbbell straight up, keeping your off hand in place. Do not lean or jerk the weight during the movement. After a brief pause, return the weight to the starting position. Repeat for the opposite side, continuing to alternate between arms.'),
('Standing_Barbell_Calf_Raise', 'Standing Barbell Calf Raise', 'legs', ARRAY[]::text[], 'barbell', 'strength', 'beginner', 'This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the bar on the back of your shoulders (slightly below the neck). Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs using a '),
('Standing_Barbell_Press_Behind_Neck', 'Standing Barbell Press Behind Neck', 'shoulders', ARRAY['arms']::text[], 'barbell', 'strength', 'intermediate', 'This exercise is best performed inside a squat rack for easier pick up of the bar. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs'),
('Standing_Bent-Over_One-Arm_Dumbbell_Triceps_Extension', 'Standing Bent-Over One-Arm Dumbbell Triceps Extension', 'arms', ARRAY['shoulders']::text[], 'dumbbell', 'strength', 'beginner', 'With a dumbbell in one hand and the palm facing your torso, bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Make sure that you keep the head up. The upper arm should be close to the torso and parallel to the floor while the forearm is pointing towards the floor as the hand holds the weight. Tip: There should be a 90-degree angle between the forearm and the upper arm. This is your starting po'),
('Standing_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension', 'Standing Bent-Over Two-Arm Dumbbell Triceps Extension', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'With a dumbbell in each hand and the palms facing your torso, bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Make sure that you keep the head up. The upper arms should be close to the torso and parallel to the floor while the forearms are pointing towards the floor as the hands hold the weights. Tip: There should be a 90-degree angle between the forearms and the upper arm. This is your star'),
('Standing_Biceps_Cable_Curl', 'Standing Biceps Cable Curl', 'arms', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Stand up with your torso upright while holding a cable curl bar that is attached to a low pulley. Grab the cable bar at shoulder width and keep the elbows close to the torso. The palm of your hands should be facing up (supinated grip). This will be your starting position. While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder l'),
('Standing_Biceps_Stretch', 'Standing Biceps Stretch', 'arms', ARRAY['chest','shoulders']::text[], 'other', 'stretching', 'beginner', 'Clasp your hands behind your back with your palms together, straighten arms and then rotate them so your palms face downward. Raise your arms up and hold until you feel a stretch in your biceps.'),
('Standing_Bradford_Press', 'Standing Bradford Press', 'shoulders', ARRAY['arms']::text[], 'barbell', 'strength', 'beginner', 'Place a loaded bar at shoulder level in a rack. With a pronated grip at shoulder width, begin with the bar racked across the front of your shoulders. This is your starting position. Initiate the lift by extending the elbows to press the bar overhead. Avoid locking out the elbow as you move the weight behind your head. Lower the bar down to the back of the head until your elbow forms a right angle. Lift the bar back over your head by extending the elbows Lower the bar down to the starting positio'),
('Standing_Cable_Chest_Press', 'Standing Cable Chest Press', 'chest', ARRAY['shoulders','arms']::text[], 'cable', 'strength', 'beginner', 'Position dual pulleys to chest height and select an appropriate weight. Stand a foot or two in front of the cables, holding one in each hand. You can stagger your stance for better stability. Position the upper arm at a 90 degree angle with the shoulder blades together. This will be your starting position. Keeping the rest of the body stationary, extend through the elbows to press the handles forward, drawing them together in front of you. Pause at the top of the motion, and return to the starti'),
('Standing_Cable_Lift', 'Standing Cable Lift', 'core', ARRAY['shoulders']::text[], 'cable', 'strength', 'beginner', 'Connect a standard handle on a tower, and move the cable to the lowest pulley position. With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Your outstretched arm should be aligned with the cable. With your feet positioned shoulder width apart, squat down and grab the handle with both hands. Your arms should still be fully extended. In one motion, pull ')
